//! `sermofur_daemon::framing` against the table that the .NET `Framing` produced
//! (`rust/tests/golden/framing.json`, regenerated by `rust/tools/framing-oracle`): every encoded
//! frame byte for byte, every read of a forged stream (message, refusal, bytes consumed), and the
//! string escaping of every scalar value.

use std::io::Cursor;

use serde_json::Value;
use sermofur_daemon::framing::{
    self, CURRENT_PROTOCOL, FrameError, IpcMessage, MAX_BODY_BYTES, MAX_RESPONSE_BYTES, kind,
};
use sha2::{Digest, Sha256};

fn golden() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/framing.json"
    );
    let text = std::fs::read_to_string(path).expect("the golden file exists");
    serde_json::from_str(&text).expect("the golden file is valid JSON")
}

fn base64(text: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let (mut acc, mut bits) = (0u32, 0);
    for b in text.bytes().filter(|b| *b != b'=') {
        let v = match b {
            b'A'..=b'Z' => b - b'A',
            b'a'..=b'z' => b - b'a' + 26,
            b'0'..=b'9' => b - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => panic!("not base64: {b}"),
        };
        acc = (acc << 6) | u32::from(v);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(u8::try_from((acc >> bits) & 0xFF).expect("a byte"));
        }
    }
    out
}

fn usize_of(value: &Value) -> usize {
    usize::try_from(value.as_u64().expect("a number")).expect("fits")
}

/// A string of the golden: plain, `{repeat, count}`, or `{utf16}` for a .NET string that holds a
/// lone surrogate. A Rust string cannot hold one, so it becomes U+FFFD, the scalar that the .NET
/// writer puts in its place, as the escape `\uFFFD` (`lone_*_surrogate_in_*` encode cases); no
/// decoded message of the golden holds one, the reader refuses them.
fn text(value: &Value) -> String {
    match value {
        Value::String(s) => s.clone(),
        Value::Object(o) if o.contains_key("utf16") => String::from_utf16_lossy(
            &o["utf16"]
                .as_array()
                .expect("an array")
                .iter()
                .map(|u| u16::try_from(u.as_u64().expect("a unit")).expect("a UTF-16 unit"))
                .collect::<Vec<_>>(),
        ),
        Value::Object(o) if o.contains_key("repeat") => o["repeat"]
            .as_str()
            .expect("a text")
            .repeat(usize_of(&o["count"])),
        other => panic!("unexpected string description {other}"),
    }
}

fn opt_text(o: &Value, name: &str) -> Option<String> {
    o.get(name).map(text)
}

fn opt_i32(o: &Value, name: &str) -> Option<i32> {
    o.get(name)
        .map(|v| i32::try_from(v.as_i64().expect("an integer")).expect("an int"))
}

/// The message that the oracle described.
fn message(o: &Value) -> IpcMessage {
    IpcMessage {
        kind: text(&o["kind"]),
        protocol: opt_i32(o, "protocol"),
        tool_version: opt_text(o, "toolVersion"),
        cwd: opt_text(o, "cwd"),
        pid: opt_i32(o, "pid"),
        id: o.get("id").map(|v| v.as_i64().expect("a long")),
        argv: o.get("argv").map(|a| {
            a.as_array()
                .expect("an array")
                .iter()
                .map(|item| (!item.is_null()).then(|| text(item)))
                .collect()
        }),
        exit_code: opt_i32(o, "exitCode"),
        stdout: opt_text(o, "stdout"),
        stderr: opt_text(o, "stderr"),
        code: opt_text(o, "code"),
        message: opt_text(o, "message"),
        started_at: opt_text(o, "startedAt"),
        instances_open: opt_i32(o, "instancesOpen"),
        clients: opt_i32(o, "clients"),
        registry: opt_text(o, "registry"),
    }
}

fn error_of(o: &Value) -> (String, String, i32) {
    assert!(o.get("unhandled").is_none(), "the oracle let through {o}");
    (
        o["code"].as_str().expect("a code").to_owned(),
        o["message"].as_str().expect("a message").to_owned(),
        i32::try_from(o["exitCode"].as_i64().expect("an exit code")).expect("fits"),
    )
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02X}")).collect()
}

#[test]
fn constants_are_those_of_the_oracle() {
    let g = golden();
    assert_eq!(MAX_BODY_BYTES, usize_of(&g["maxBodyBytes"]));
    assert_eq!(MAX_RESPONSE_BYTES, usize_of(&g["maxResponseBytes"]));
    assert_eq!(
        i64::from(CURRENT_PROTOCOL),
        g["currentProtocol"].as_i64().unwrap()
    );
    let kinds: Vec<&str> = g["kinds"]
        .as_array()
        .unwrap()
        .iter()
        .map(|k| k.as_str().unwrap())
        .collect();
    assert_eq!(
        kinds,
        [
            kind::HELLO,
            kind::WELCOME,
            kind::RUN,
            kind::RESULT,
            kind::NOT_SERVING,
            kind::STATUS,
            kind::SHUTDOWN,
            kind::STOPPING,
            kind::ERROR
        ]
    );
}

#[test]
fn every_frame_is_encoded_byte_for_byte() {
    let g = golden();
    let cases = g["encode"].as_array().unwrap();
    assert!(cases.len() >= 30);
    assert!(
        cases
            .iter()
            .any(|c| c["name"] == "lone_high_surrogate_in_stdout"),
        "the lone surrogate cases are recorded"
    );
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let built = message(&case["message"]);
        let result = framing::encode(&built, usize_of(&case["limit"]));
        if let Some(error) = case.get("error") {
            let refusal = result.expect_err(name);
            assert_eq!(
                (refusal.code, refusal.message, refusal.exit_code),
                error_of(error),
                "{name}"
            );
            continue;
        }
        let frame = result.unwrap_or_else(|e| panic!("{name}: {e}"));
        let expected = &case["frame"];
        if case["message"].to_string().contains("\"utf16\"") {
            // Skipped byte comparison, reason: lone surrogate. The oracle writes it as the escape
            // `\uFFFD`; the port, given U+FFFD, writes the scalar raw (EF BF BD), as the oracle
            // does for a real U+FFFD. Both frames read back as the same message.
            let theirs = base64(expected["base64"].as_str().unwrap());
            assert_eq!(framing::decode(&theirs[4..]).unwrap(), built, "{name}");
            assert_eq!(framing::decode(&frame[4..]).unwrap(), built, "{name}");
        } else if let Some(b64) = expected.get("base64") {
            assert_eq!(frame, base64(b64.as_str().unwrap()), "{name}");
        } else {
            assert_eq!(frame.len(), usize_of(&expected["length"]), "{name}");
            assert_eq!(
                hex(&Sha256::digest(&frame)),
                expected["sha256"].as_str().unwrap(),
                "{name}"
            );
        }
    }
}

#[test]
fn every_forged_stream_reads_as_the_oracle_reads_it() {
    let g = golden();
    let cases = g["decode"].as_array().unwrap();
    assert!(cases.len() >= 100);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let mut input = Vec::new();
        for segment in case["input"].as_array().unwrap() {
            if let Some(b64) = segment.get("base64") {
                input.extend(base64(b64.as_str().unwrap()));
            } else {
                let byte = u8::try_from(segment["repeat"].as_u64().unwrap()).unwrap();
                input.extend(std::iter::repeat_n(byte, usize_of(&segment["count"])));
            }
        }
        let limit = usize_of(&case["limit"]);
        let mut stream = Cursor::new(input);
        for outcome in case["outcomes"].as_array().unwrap() {
            let read = framing::read(&mut stream, limit);
            if outcome.get("end").is_some() {
                assert!(matches!(read, Ok(None)), "{name}: {read:?}");
            } else if let Some(expected) = outcome.get("message") {
                let got = read.unwrap_or_else(|e| panic!("{name}: {e:?}"));
                assert_eq!(got, Some(message(expected)), "{name}");
            } else {
                let Err(FrameError::Refused(refusal)) = read else {
                    panic!("{name}: expected a refusal, got {read:?}");
                };
                assert_eq!(
                    (refusal.code, refusal.message, refusal.exit_code),
                    error_of(&outcome["error"]),
                    "{name}"
                );
            }
        }
        assert_eq!(
            stream.position(),
            case["consumed"].as_u64().unwrap(),
            "{name}: bytes consumed"
        );
    }
}

/// The JSON text of a one-character `kind`, without its quotes.
fn escaped_form(text: &str) -> String {
    let frame = framing::encode(&IpcMessage::new(text), MAX_BODY_BYTES).expect("encodes");
    let body = std::str::from_utf8(&frame[4..]).expect("UTF-8");
    body["{\"kind\":\"".len()..body.len() - 2].to_owned()
}

#[test]
fn every_scalar_is_escaped_as_the_relaxed_encoder_does() {
    let g = golden();
    let escape = &g["escape"];
    let mut specials = std::collections::HashMap::new();
    for pair in escape["specials"].as_array().unwrap() {
        specials.insert(
            u32::try_from(pair[0].as_u64().unwrap()).unwrap(),
            pair[1].as_str().unwrap().to_owned(),
        );
    }
    let ranges: Vec<(u32, u32)> = escape["unicodeEscapedRanges"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| {
            (
                u32::try_from(r[0].as_u64().unwrap()).unwrap(),
                u32::try_from(r[1].as_u64().unwrap()).unwrap(),
            )
        })
        .collect();
    for scalar in (0..=0xFFFFu32).filter(|s| !(0xD800..=0xDFFF).contains(s)) {
        let c = char::from_u32(scalar).unwrap();
        let expected = if let Some(special) = specials.get(&scalar) {
            special.clone()
        } else if ranges.iter().any(|&(a, b)| (a..=b).contains(&scalar)) {
            format!("\\u{scalar:04X}")
        } else {
            c.to_string()
        };
        assert_eq!(escaped_form(&c.to_string()), expected, "U+{scalar:04X}");
    }
    for sample in escape["supplementarySamples"].as_array().unwrap() {
        let scalar = u32::try_from(sample[0].as_u64().unwrap()).unwrap();
        let c = char::from_u32(scalar).unwrap();
        assert_eq!(
            escaped_form(&c.to_string()),
            sample[1].as_str().unwrap(),
            "U+{scalar:X}"
        );
    }
}
